import sys
from itertools import combinations

def solve():
    MOD = 998244353
    N = int(input())
    points = [tuple(map(int, input().split())) for _ in range(N)]

    x_sorted = sorted(set(x for x, _ in points))
    y_sorted = sorted(set(y for _, y in points))

    x_map = {x: i for i, x in enumerate(x_sorted)}
    y_map = {y: i for i, y in enumerate(y_sorted)}

    grid = [[0] * (len(y_sorted) + 1) for _ in range(len(x_sorted) + 1)]

    for x, y in points:
        grid[x_map[x] + 1][y_map[y] + 1] = 1

    for i in range(len(x_sorted)):
        for j in range(len(y_sorted)):
            grid[i + 1][j + 1] += grid[i][j + 1] + grid[i + 1][j] - grid[i][j]

    result = 0
    for k in range(1, N + 1):
        for subset in combinations(points, k):
            x_min = min(x for x, _ in subset)
            x_max = max(x for x, _ in subset)
            y_min = min(y for _, y in subset)
            y_max = max(y for _, y in subset)

            x1, x2 = x_map[x_min], x_map[x_max] + 1
            y1, y2 = y_map[y_min], y_map[y_max] + 1

            count = grid[x2][y2] - grid[x1][y2] - grid[x2][y1] + grid[x1][y1]
            result = (result + count) % MOD

    print(result)

if __name__ == "__main__":
    solve()
